// (1) C++17 RingBuffer<T>
#include <cstddef>
#include <stdexcept>
#include <vector>
#include <iostream>

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity)
        : data_(capacity), head_(0), tail_(0), count_(0) {}

    void push(const T& value) {
        if (count_ == data_.size()) {
            throw std::overflow_error("RingBuffer is full");
        }
        data_[(head_ + count_) % data_.size()] = value;
        ++count_;
    }

    T pop() {
        if (count_ == 0) {
            throw std::underflow_error("RingBuffer is empty");
        }
        T value = data_[tail_];
        ++tail_;
        --count_;
        return value;
    }

    std::size_t size() const { return count_; }
    std::size_t capacity() const { return data_.size(); }

private:
    std::vector<T> data_;
    std::size_t head

